-- BoiForte: módulo de Cria separado (grupos de manejo, matrizes, touros, bezerros, reprodução e desmama).
--
-- O que esta migração faz (não cria tabela no Postgres: os registros do app ficam em "registros", como os outros;
-- aqui só entram as regras de validação e a lista do que o vaqueiro vê e grava):
--   1. Tabelas novas do app, conferidas pelo servidor como as demais (bloco GERADO abaixo):
--        grupos      grupo de manejo da Cria (no lugar de "lote"), com piquete e "encerrado"
--        estacoes    estação de monta (monta natural, IA, IATF, IA com repasse)
--        reproducao  monta, inseminação, diagnóstico de gestação, parto e aborto de cada vaca
--        pesosCria   pesagens dos animais da Cria (nascimento até a desmama)
--        desmamas    pacote da desmama (pesos, sexo, idade de cada bezerro, versão no ano) que vira lote de Recria/RIP
--   2. "animais" ganha os campos da Cria: grupoId, categoria (matriz, novilha, touro, bezerro), chip, sisbov (15 dígitos),
--      nome, nascimento, maeId e paiId (outros animais da MESMA fazenda, conferido pelo servidor), paiTexto (sêmen),
--      foto, pesoNascer, creep, formulaCreepId, entrada, permanenciaMeses, qtd (touros por lote), saida, motivoSaida,
--      descarte, motivoDescarte e obs. "loteId" passa a ser opcional (animal da Cria fica só com o grupo).
--   3. "sanidade" pode ser de um grupo ou animal da Cria (loteId, grupoId e animalId opcionais);
--      "lancamentos" ganha grupoId (despesa da Cria, entra no custo do bezerro desmamado).
--   4. Vaqueiro: VÊ grupos, estações, reprodução, pesagens da Cria e desmamas (nada disso tem dinheiro);
--      GRAVA reprodução (cobertura, diagnóstico, parto) e pesagens da Cria, além de animais (nascimento), que já gravava.
--      Grupos, estação de monta e desmama (que cria lote) ficam só com dono e gerente.
--
-- Depende de 20261124130000_fase_rip_tip.sql (e das anteriores). Se o Pasto (20261124150000) também mudar
-- bf_vaqueiro_le/bf_vaqueiro_grava, a lista desta migração precisa incluir as tabelas dele (quem rodar por último manda).

create or replace function public.bf_vaqueiro_le() returns text[] language sql immutable as $$
  select array['propriedades','modulos','piquetes','lotes','animais','pesagens','ingredientes','formulas','movimentos','batidas','fornecimentos','sanidade','lembretes','config','anotacoes',
               'grupos','estacoes','reproducao','pesosCria','desmamas']
$$;
create or replace function public.bf_vaqueiro_grava() returns text[] language sql immutable as $$
  select array['animais','pesagens','fornecimentos','movimentos','sanidade','lotes','lancamentos','anotacoes','reproducao','pesosCria']
$$;

